import { clearCandidateTSConfigRootDirs, addCandidateTSConfigRootDir, getInferredTSConfigRootDir } from '@typescript-eslint/typescript-estree';
import path from 'node:path';

// Simulate what happens when both root and frontend eslint configs load in one ESLint LS process
clearCandidateTSConfigRootDirs();
addCandidateTSConfigRootDir(path.resolve('.'));
addCandidateTSConfigRootDir(path.resolve('apps/frontend'));

try {
	getInferredTSConfigRootDir();
	console.log('FAIL: inference should throw with multiple candidates');
} catch (e) {
	console.log('OK: inference throws as expected when unset:\n', e.message.split('\n')[0]);
}

// Load configs the way the IDE would
const rootConfig = (await import('./eslint.config.js')).default;
const frontendConfig = (await import('./apps/frontend/eslint.config.js')).default;

function findTsconfigRootDirs(configs, label) {
	const dirs = [];
	for (const c of configs) {
		const dir = c?.languageOptions?.parserOptions?.tsconfigRootDir;
		if (dir) dirs.push(dir);
	}
	console.log(`${label} explicit tsconfigRootDir entries:`, dirs);
}

findTsconfigRootDirs(rootConfig, 'root');
findTsconfigRootDirs(frontendConfig, 'frontend');

// Confirm merged-style presence: every config array now has at least one explicit setting
const rootHas = rootConfig.some(c => c?.languageOptions?.parserOptions?.tsconfigRootDir);
const frontendHas = frontendConfig.some(c => c?.languageOptions?.parserOptions?.tsconfigRootDir);
console.log('root has explicit tsconfigRootDir:', rootHas);
console.log('frontend has explicit tsconfigRootDir:', frontendHas);
if (!rootHas || !frontendHas) process.exit(1);
EOF

