import estree from '@typescript-eslint/typescript-estree';
import path from 'node:path';

const {
	clearCandidateTSConfigRootDirs,
	addCandidateTSConfigRootDir,
	getInferredTSConfigRootDir,
} = estree;

clearCandidateTSConfigRootDirs();
addCandidateTSConfigRootDir(path.resolve('.'));
addCandidateTSConfigRootDir(path.resolve('apps/frontend'));

try {
	getInferredTSConfigRootDir();
	console.log('FAIL: inference should throw');
	process.exit(1);
} catch (e) {
	console.log('OK: multi-candidate inference still throws without explicit setting');
}

const rootConfig = (await import('./eslint.config.js')).default;
const frontendConfig = (await import('./apps/frontend/eslint.config.js')).default;
const backendConfig = (await import('./apps/backend/eslint.config.js')).default;

for (const [label, configs] of [
	['root', rootConfig],
	['frontend', frontendConfig],
	['backend', backendConfig],
]) {
	const dirs = configs
		.map(c => c?.languageOptions?.parserOptions?.tsconfigRootDir)
		.filter(Boolean);
	console.log(`${label}:`, dirs.length ? dirs : 'MISSING');
	if (!dirs.length) process.exit(1);
}

// Simulate parser path: with explicit option, createParseSettings should not infer
const { createParseSettings } = await import('@typescript-eslint/typescript-estree/dist/parseSettings/createParseSettings.js').catch(() => ({ createParseSettings: null }));
// Just verify configs themselves — createParseSettings may not be exported cleanly
console.log('All eslint configs set tsconfigRootDir explicitly.');
EOF
